import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const issues = sqliteTable(
  "issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    number: integer("number").notNull(),
    title: text("title").notNull(),
    description: text("description"),
    status: text("status", {
      enum: ["backlog", "todo", "in_progress", "in_review", "done", "canceled"],
    })
      .notNull()
      .default("backlog"),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    authorId: text("author_id").notNull(),
    assigneeId: text("assignee_id"),
    parentId: text("parent_id"),
    estimate: integer("estimate"),
    dueAt: text("due_at"),
    startedAt: text("started_at"),
    completedAt: text("completed_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("issues_project_number_idx").on(table.projectId, table.number),
    index("issues_org_status_idx").on(table.orgId, table.status),
    index("issues_org_assignee_idx").on(table.orgId, table.assigneeId),
    index("issues_org_archived_idx").on(table.orgId, table.archivedAt),
    index("issues_org_due_idx").on(table.orgId, table.dueAt),
  ],
);

export const labels = sqliteTable(
  "labels",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    color: text("color").notNull().default("#94a3b8"),
    description: text("description"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("labels_org_name_idx").on(table.orgId, table.name)],
);

export const issueLabels = sqliteTable(
  "issue_labels",
  {
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    labelId: text("label_id").notNull(),
  },
  (table) => [
    uniqueIndex("issue_labels_pk").on(table.issueId, table.labelId),
    index("issue_labels_org_idx").on(table.orgId),
  ],
);

export const attachments = sqliteTable(
  "attachments",
  {
    id: idColumn(),
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    uploadedBy: text("uploaded_by").notNull(),
    ...timestampColumns,
  },
  (table) => [index("attachments_org_issue_idx").on(table.orgId, table.issueId)],
);

export type IssueRow = typeof issues.$inferSelect;
export type NewIssueRow = typeof issues.$inferInsert;
export type LabelRow = typeof labels.$inferSelect;
export type AttachmentRow = typeof attachments.$inferSelect;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const projects = sqliteTable(
  "projects",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    key: text("key").notNull(),
    description: text("description"),
    visibility: text("visibility", { enum: ["private", "org", "public"] })
      .notNull()
      .default("org"),
    status: text("status", { enum: ["active", "paused", "completed"] })
      .notNull()
      .default("active"),
    leadId: text("lead_id"),
    color: text("color").notNull().default("#6366f1"),
    startsAt: text("starts_at"),
    targetDate: text("target_date"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("projects_org_slug_idx").on(table.orgId, table.slug),
    uniqueIndex("projects_org_key_idx").on(table.orgId, table.key),
    index("projects_org_archived_idx").on(table.orgId, table.archivedAt),
  ],
);

export const projectMembers = sqliteTable(
  "project_members",
  {
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    userId: text("user_id").notNull(),
    addedAt: text("added_at").notNull(),
  },
  (table) => [
    uniqueIndex("project_members_pk").on(table.projectId, table.userId),
    index("project_members_org_idx").on(table.orgId),
  ],
);

export type ProjectRow = typeof projects.$inferSelect;
export type NewProjectRow = typeof projects.$inferInsert;
export type ProjectMemberRow = typeof projectMembers.$inferSelect;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const subscriptions = sqliteTable(
  "subscriptions",
  {
    id: idColumn(),
    ...tenantColumns,
    plan: text("plan", { enum: ["free", "starter", "growth", "enterprise"] })
      .notNull()
      .default("free"),
    interval: text("interval", { enum: ["monthly", "annual"] })
      .notNull()
      .default("monthly"),
    status: text("status", {
      enum: ["trialing", "active", "past_due", "canceled"],
    })
      .notNull()
      .default("trialing"),
    seats: integer("seats").notNull().default(1),
    currentPeriodStart: text("current_period_start").notNull(),
    currentPeriodEnd: text("current_period_end").notNull(),
    cancelAt: text("cancel_at"),
    ...timestampColumns,
  },
  (table) => [index("subscriptions_org_idx").on(table.orgId)],
);

export const invoices = sqliteTable(
  "invoices",
  {
    id: idColumn(),
    ...tenantColumns,
    number: text("number").notNull(),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("usd"),
    periodStart: text("period_start").notNull(),
    periodEnd: text("period_end").notNull(),
    paidAt: text("paid_at"),
    ...timestampColumns,
  },
  (table) => [index("invoices_org_period_idx").on(table.orgId, table.periodStart)],
);

export type SubscriptionRow = typeof subscriptions.$inferSelect;
export type NewSubscriptionRow = typeof subscriptions.$inferInsert;
export type InvoiceRow = typeof invoices.$inferSelect;

import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const comments = sqliteTable(
  "comments",
  {
    id: idColumn(),
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    authorId: text("author_id").notNull(),
    body: text("body").notNull(),
    parentId: text("parent_id"),
    editedAt: text("edited_at"),
    /** JSON array of user ids, kept denormalised for the mention fan-out. */
    mentionedUserIds: text("mentioned_user_ids").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    index("comments_org_issue_idx").on(table.orgId, table.issueId),
    index("comments_org_archived_idx").on(table.orgId, table.archivedAt),
  ],
);

export type CommentRow = typeof comments.$inferSelect;
export type NewCommentRow = typeof comments.$inferInsert;

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, softDeleteColumns, timestampColumns } from "./_shared";

export const organizations = sqliteTable(
  "organizations",
  {
    id: idColumn(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    ownerId: text("owner_id").notNull(),
    plan: text("plan", {
      enum: ["free", "starter", "growth", "enterprise"],
    })
      .notNull()
      .default("free"),
    logoUrl: text("logo_url"),
    trialEndsAt: text("trial_ends_at"),
    defaultIssueStatus: text("default_issue_status").notNull().default("backlog"),
    allowPublicProjects: integer("allow_public_projects", { mode: "boolean" })
      .notNull()
      .default(false),
    requireTwoFactor: integer("require_two_factor", { mode: "boolean" })
      .notNull()
      .default(false),
    digestHourUtc: integer("digest_hour_utc").notNull().default(7),
    enabledFlagOverrides: text("enabled_flag_overrides").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("organizations_slug_idx").on(table.slug),
    index("organizations_owner_idx").on(table.ownerId),
  ],
);

export const organizationUsage = sqliteTable("organization_usage", {
  orgId: text("org_id").primaryKey(),
  seatsUsed: integer("seats_used").notNull().default(0),
  projectsUsed: integer("projects_used").notNull().default(0),
  issuesUsed: integer("issues_used").notNull().default(0),
  storageMbUsed: integer("storage_mb_used").notNull().default(0),
  measuredAt: text("measured_at").notNull(),
});

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;

import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, timestampColumns } from "./_shared";

/** Users are global, not tenant-scoped: one account can join many orgs. */
export const users = sqliteTable(
  "users",
  {
    id: idColumn(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    avatarUrl: text("avatar_url"),
    timezone: text("timezone").notNull().default("UTC"),
    emailVerifiedAt: text("email_verified_at"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("users_email_idx").on(table.email)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    id: idColumn(),
    userId: text("user_id").notNull(),
    activeOrgId: text("active_org_id"),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("sessions_token_idx").on(table.tokenHash)],
);

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: idColumn(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  ...timestampColumns,
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
export type SessionRow = typeof sessions.$inferSelect;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const members = sqliteTable(
  "members",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    status: text("status", { enum: ["active", "invited", "suspended"] })
      .notNull()
      .default("active"),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at"),
    lastSeenAt: text("last_seen_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("members_org_user_idx").on(table.orgId, table.userId),
    index("members_org_role_idx").on(table.orgId, table.role),
  ],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: idColumn(),
    ...tenantColumns,
    email: text("email").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    invitedBy: text("invited_by").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    acceptedAt: text("accepted_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("invitations_token_idx").on(table.tokenHash),
    index("invitations_org_email_idx").on(table.orgId, table.email),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;

import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns } from "./_shared";

export const activityEvents = sqliteTable(
  "activity_events",
  {
    id: idColumn(),
    ...tenantColumns,
    action: text("action").notNull(),
    actorId: text("actor_id"),
    subjectKind: text("subject_kind", {
      enum: [
        "organization",
        "project",
        "issue",
        "comment",
        "member",
        "subscription",
        "feature_flag",
      ],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    summary: text("summary").notNull(),
    /** JSON object of scalar metadata. */
    metadata: text("metadata").notNull().default("{}"),
    occurredAt: text("occurred_at").notNull(),
  },
  (table) => [
    index("activity_org_occurred_idx").on(table.orgId, table.occurredAt),
    index("activity_org_action_idx").on(table.orgId, table.action),
    index("activity_org_subject_idx").on(table.orgId, table.subjectKind, table.subjectId),
  ],
);

export type ActivityEventRow = typeof activityEvents.$inferSelect;
export type NewActivityEventRow = typeof activityEvents.$inferInsert;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const webhookEndpoints = sqliteTable(
  "webhook_endpoints",
  {
    id: idColumn(),
    ...tenantColumns,
    url: text("url").notNull(),
    secret: text("secret").notNull(),
    /** JSON array of `TaskflowEventType`. */
    eventTypes: text("event_types").notNull().default("[]"),
    enabled: integer("enabled", { mode: "boolean" }).notNull().default(true),
    ...timestampColumns,
  },
  (table) => [index("webhook_endpoints_org_idx").on(table.orgId)],
);

export const webhookDeliveries = sqliteTable(
  "webhook_deliveries",
  {
    id: idColumn(),
    ...tenantColumns,
    endpointId: text("endpoint_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: text("payload").notNull(),
    status: text("status", { enum: ["pending", "delivered", "failed"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastError: text("last_error"),
    deliveredAt: text("delivered_at"),
    ...timestampColumns,
  },
  (table) => [
    index("webhook_deliveries_org_status_idx").on(table.orgId, table.status),
  ],
);

/** Token-bucket state for `src/lib/rate-limit.ts`, persisted per org+key. */
export const rateLimitBuckets = sqliteTable(
  "rate_limit_buckets",
  {
    id: idColumn(),
    ...tenantColumns,
    bucketKey: text("bucket_key").notNull(),
    tokens: integer("tokens").notNull(),
    refilledAt: text("refilled_at").notNull(),
  },
  (table) => [index("rate_limit_org_key_idx").on(table.orgId, table.bucketKey)],
);

/** Denormalised full-text index maintained by `SearchService`. */
export const searchIndex = sqliteTable(
  "search_index",
  {
    id: idColumn(),
    ...tenantColumns,
    subjectKind: text("subject_kind", {
      enum: ["issue", "comment", "project"],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    content: text("content").notNull(),
    indexedAt: text("indexed_at").notNull(),
  },
  (table) => [
    index("search_index_org_kind_idx").on(table.orgId, table.subjectKind),
  ],
);

export type WebhookEndpointRow = typeof webhookEndpoints.$inferSelect;
export type WebhookDeliveryRow = typeof webhookDeliveries.$inferSelect;
export type SearchIndexRow = typeof searchIndex.$inferSelect;
